function normalizeClassTag(value){
  const raw=String(value||"").trim();
  if(!raw) return "Placeholder";
  const key=raw.toLocaleLowerCase("en-US").replace(/[^a-z0-9]/g,"");
  const aliases={
    bloodhunter:"Bloodhunter"
  };
  return aliases[key]||raw;
}

function normalizeRaceTag(value){
  const raw=String(value||"").trim();
  if(!raw) return "Placeholder";
  const key=raw.toLocaleLowerCase("en-US").replace(/[\s-]/g,"");
  const aliases={
    halfelf:"Half-Elf",
    shaddarkai:"Shaddar-Kai",
    yuanti:"Yuan-Ti"
  };
  return aliases[key]||raw;
}

/* Xavier występuje dwukrotnie z tym samym graczem, ale są to dwie różne postaci. */
CHARACTER_META.set("Xavier\\u0000archangelss\\u0000Echtra - Zima Irgaeli",{classes:["Monk"],race:"Dragonborn"});

for(const record of records){
  const key=record.name+"\u0000"+canonicalPlayer(record.tags.player[0]||"");
  const campaignKey=record.name+"\u0000"+canonicalPlayer(record.tags.player[0]||"")+"\u0000"+(record.tags.campaign[0]||"");
  const meta=GRAPHIC_META_OVERRIDES.get(campaignKey)||CHARACTER_META.get(campaignKey)||CHARACTER_META.get(key);
  if(meta){
    record.tags.class=(meta.classes.length?meta.classes:["Placeholder"]).map(normalizeClassTag);
    record.tags.race=[normalizeRaceTag(meta.race)];
  }else{
    record.tags.class=["Placeholder"];
    record.tags.race=["Placeholder"];
  }
}

/* CoC 7e — investigatorzy. */
const COC7E_INVESTIGATORS=new Set([
  "Mattia",
  "Samuel Wokulski",
  "Vincent Campbell",
  "Lorenzo Dal",
  "Audrey Fulton",
  "Dan Whelan",
  "Patty Graham"
]);
for(const record of records){
  if(COC7E_INVESTIGATORS.has(record.name)){
    record.tags.class=["CoC7e Investigator"];
    record.tags.race=["CoC7e Investigator"];
  }
}

/* Rasa Cala była zgłoszona jako HalfElf; zachowujemy ją również przy ewentualnych wariantach aliasu gracza. */
for(const record of records){
  if(record.name==="Cal" && canonicalPlayer(record.tags.player[0])==="lexonis"){
    record.tags.class=["Warlock"];
    record.tags.race=["Half-Elf"];
  }
}

/* Korekty graczy wynikające z najnowszej kartoteki. */
for(const record of records){
  if(record.name==="Erro") record.tags.player=["Marcin"];
  if(record.name==="Theron") record.tags.player=["shrimphead"];
}

/* Elorin — Michał został usunięty z kartoteki na życzenie. */
for(let i=records.length-1;i>=0;i--){
  if(records[i].name==="Elorin") records.splice(i,1);
}

/* Alias danych do dalszego rozszerzania archiwum. */
const characterRegistry=records;

const $=id=>document.getElementById(id);
const norm=s=>String(s??"")
  .toLocaleLowerCase("pl-PL")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g,"");

const grid=$("hallGrid");
const search=$("search");
const filters={
  campaign:$("campaignFilter"),
  class:$("classFilter"),
  race:$("raceFilter"),
  fate:$("fateFilter"),
  player:$("playerFilter")
};

function allTags(type){
  return [...new Set(characterRegistry.flatMap(record=>record.tags[type]||[]))]
    .filter(Boolean)
    .sort((a,b)=>a.localeCompare(b,"pl"));
}

function populateFilter(select,type,emptyLabel){
  select.innerHTML="";
  const first=document.createElement("option");
  first.value="";
  first.textContent=emptyLabel;
  select.append(first);

  for(const tag of allTags(type)){
    const option=document.createElement("option");
    option.value=tag;
    option.textContent=tag;
    select.append(option);
  }
}

populateFilter(filters.campaign,"campaign","Wszystkie kampanie");
populateFilter(filters.class,"class","Wszystkie klasy");
populateFilter(filters.race,"race","Wszystkie rasy");
populateFilter(filters.fate,"fate","Wszystkie losy");
populateFilter(filters.player,"player","Wszyscy gracze");

$("countAll").textContent=characterRegistry.length;
$("countDead").textContent=characterRegistry.filter(x=>x.tags.fate.includes("dead")).length;
$("countCampaigns").textContent=allTags("campaign").length;
$("countPlayers").textContent=allTags("player").filter(x=>x!=="NPC"&&x!=="Nie podano").length;

function tagMarkup(type,tags){
  return (tags||[]).map(tag=>
    '<span class="tag tag-'+type+'">'+tag+'</span>'
  ).join("");
}

function matches(record){
  const query=norm(search.value.trim());
  if(query){
    const searchable=[
      record.name,
      record.description,
      ...Object.values(record.tags).flat()
    ].join(" ");
    if(!norm(searchable).includes(query)) return false;
  }

  for(const type of Object.keys(filters)){
    const value=filters[type].value;
    if(value && !record.tags[type].includes(value)) return false;
  }

  return true;
}

function escapeHtml(value){
  return String(value??"").replace(/[&<>"']/g,char=>({
    "&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"
  }[char]));
}

function openCharacter(record){
  const modal=$("characterModal");
  const content=$("modalContent");
  const fate=record.tags.fate[0]||"unknown";
  const note=String(record.note??"").trim();

  content.innerHTML=
    '<div class="modal-left">'+
      '<img class="modal-portrait" src="'+escapeHtml(record.portrait)+'" alt="'+escapeHtml(record.name)+'">'+
      '<div class="modal-identity">'+
        '<span class="modal-kicker">REKORD POSTACI</span>'+
        '<h2 id="modalCharacterName">'+escapeHtml(record.name)+'</h2>'+
        '<div class="modal-meta">'+
          '<div class="modal-meta-row"><b>Tagi kampanii</b><span class="modal-tags">'+tagMarkup("campaign",record.tags.campaign)+'</span></div>'+
          '<div class="modal-meta-row"><b>Tagi klasy</b><span class="modal-tags">'+tagMarkup("class",record.tags.class)+'</span></div>'+
          '<div class="modal-meta-row"><b>Tagi rasy</b><span class="modal-tags">'+tagMarkup("race",record.tags.race)+'</span></div>'+
          '<div class="modal-meta-row"><b>Tagi losu</b><span class="modal-tags">'+tagMarkup("fate",record.tags.fate)+'</span></div>'+
          '<div class="modal-meta-row"><b>Tagi gracza</b><span class="modal-tags">'+tagMarkup("player",record.tags.player)+'</span></div>'+
        '</div>'+
      '</div>'+
    '</div>'+
    '<div class="modal-right">'+
      '<span class="modal-right-kicker">ARCHIWUM / NOTATKA</span>'+
      '<h3>Backstory</h3>'+
      '<div class="modal-note'+(note?"":" empty-note")+'">'+escapeHtml(note||"Nie ma nic więcej do dodania")+'</div>'+
      '<div class="modal-fate"><strong>'+escapeHtml(labels[fate]||"")+'</strong><br>'+escapeHtml(record.description||"")+'</div>'+
    '</div>';

  modal.hidden=false;
  modal.setAttribute("aria-hidden","false");
  document.body.classList.add("modal-open");
}

function closeCharacter(){
  const modal=$("characterModal");
  modal.hidden=true;
  modal.setAttribute("aria-hidden","true");
  document.body.classList.remove("modal-open");
}

function render(){
  const rows=characterRegistry.filter(matches);

  $("resultCount").textContent=rows.length+" / "+characterRegistry.length;

  grid.innerHTML=rows.map(record=>{
    const fate=record.tags.fate[0]||"unknown";

    return '<article class="card" data-record-index="'+characterRegistry.indexOf(record)+'" data-fate="'+fate+'" tabindex="0" role="button" aria-label="Otwórz kartę postaci '+escapeHtml(record.name)+'">'+
      '<div class="portrait">'+
        '<img src="'+record.portrait+'" alt="'+record.name+'" loading="lazy" onerror="this.remove()">'+
      '</div>'+
      '<div class="card-body">'+
        '<h3>'+record.name+'</h3>'+
        '<div class="meta">'+
          '<div><b>Tagi kampanii</b><span class="tags">'+tagMarkup("campaign",record.tags.campaign)+'</span></div>'+
          '<div><b>Tagi klasy</b><span class="tags">'+tagMarkup("class",record.tags.class)+'</span></div>'+
          '<div><b>Tagi rasy</b><span class="tags">'+tagMarkup("race",record.tags.race)+'</span></div>'+
          '<div><b>Tagi losu</b><span class="tags">'+tagMarkup("fate",record.tags.fate)+'</span></div>'+
          '<div><b>Tagi gracza</b><span class="tags">'+tagMarkup("player",record.tags.player)+'</span></div>'+
        '</div>'+
        '<div class="fate"><strong>'+labels[fate]+'</strong><br>'+record.description+'</div>'+
      '</div>'+
    '</article>';
  }).join("");

  $("empty").hidden=rows.length!==0;

  grid.querySelectorAll(".card").forEach(card=>{
    const record=characterRegistry[Number(card.dataset.recordIndex)];
    card.addEventListener("click",()=>openCharacter(record));
    card.addEventListener("keydown",event=>{
      if(event.key==="Enter"||event.key===" "){
        event.preventDefault();
        openCharacter(record);
      }
    });
  });
}

[search,...Object.values(filters)].forEach(el=>el.addEventListener("input",render));

$("clearFilters").addEventListener("click",()=>{
  search.value="";
  for(const select of Object.values(filters)) select.value="";
  render();
});

render();

$("modalClose").addEventListener("click",closeCharacter);
$("characterModal").addEventListener("click",event=>{
  if(event.target.matches("[data-modal-close]")) closeCharacter();
});
document.addEventListener("keydown",event=>{
  if(event.key==="Escape" && !$("characterModal").hidden) closeCharacter();
});

